<?php require 'common.php';require_admin();$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$stmt=$db->prepare('SELECT * FROM admins WHERE id=?');$stmt->execute([$_SESSION['admin_id']]);$a=$stmt->fetch(PDO::FETCH_ASSOC);$old=(string)($_POST['old']??'');$new=(string)($_POST['new']??'');$confirm=(string)($_POST['confirm']??'');if(!password_verify($old,$a['password_hash']))$error='Current password is incorrect.';elseif(strlen($new)<10)$error='Use at least 10 characters for your new password.';elseif($new!==$confirm)$error='New passwords do not match.';else{$stmt=$db->prepare('UPDATE admins SET password_hash=? WHERE id=?');$stmt->execute([password_hash($new,PASSWORD_DEFAULT),$a['id']]);$success='Password updated.';}}layout_start('Account security');?><div class="panel narrow"><p class="sub">Change the default password before publishing your site online.</p><?php if($error):?><p class="error"><?=h($error)?></p><?php endif;?><?php if($success):?><p class="success"><?=h($success)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Current password<input type="password" name="old" required></label><label>New password<input type="password" name="new" required minlength="10"></label><label>Confirm new password<input type="password" name="confirm" required></label><button class="primary">Update password</button></form></div><?php layout_end(); ?>
